          <th>Due {p.name}</th>
          <th>Carried {p.name}</th>
        </Fragment>""")
s=s.replace("""/** A person's due-total for each period on the sheet (fixed while the period is closed). */""","""/** A person's due-total for each period on the sheet (fixed while the period is closed), and what is carried into it. */""")
s=s.replace("""  const totals = usePersonPeriodDueTotals(sheetId).get(personId);
